<script setup lang="ts">
import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth'
const auth=useAuth(),router=useRouter();const username=ref('admin'),password=ref('Admin123!'),loading=ref(false),error=ref('')
